{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Disabled authenticator requires re-binding before use",
      "covers": [
        "KDH-039"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An authenticator has been disabled due to reaching the failed-attempt threshold defined in VBP SDD §14. The company representative account is active.",
      "test_inputs": "Credentials for the company representative account, the disabled authenticator.",
      "assumptions": "The VBP SDD §14 defines a specific threshold (e.g., 5 attempts) for disabling authenticators. The re-binding process follows NIST SP 800-63B-4 §4.1.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to authenticate using the disabled authenticator without re-binding.",
          "expected": "Authentication fails. The system indicates that the authenticator is disabled and requires re-binding."
        },
        {
          "no": 2,
          "action": "Initiate the re-binding process for the disabled authenticator to the company representative account as per NIST SP 800-63B-4 §4.1.",
          "expected": "The re-binding process completes successfully. The authenticator status changes to active/bound."
        },
        {
          "no": 3,
          "action": "Attempt to authenticate using the re-bound authenticator.",
          "expected": "Authentication succeeds. The user is granted access."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Re-binding is mandatory after threshold breach",
      "covers": [
        "KDH-039"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "An authenticator has been disabled due to reaching the failed-attempt threshold. The user has not performed re-binding.",
      "test_inputs": "The disabled authenticator.",
      "assumptions": "The system enforces the re-binding requirement strictly.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to use the disabled authenticator for authentication.",
          "expected": "The system rejects the authentication attempt and explicitly states that re-binding is required before the authenticator can be used."
        }
      ]
    }
  ]
}

